"""Instala los accesos de cliente, administrador y barbero en Barbería Capital.

Guarda este archivo junto a manage.py. Conserva respaldos antes de escribir.
"""
import ast
import base64
import json
import re
import shutil
import sqlite3
import subprocess
import sys
from datetime import datetime
from pathlib import Path

PAQUETE = ""
BASE = Path(__file__).resolve().parent


def reemplazar_funcion(texto, nombre, reemplazo):
    nodos = [n for n in ast.parse(texto).body if isinstance(n, ast.FunctionDef) and n.name == nombre]
    if len(nodos) != 1:
        raise ValueError(f"No encuentro una única función {nombre}. No se han escrito cambios.")
    nodo = nodos[0]
    lineas = texto.splitlines(keepends=True)
    return "".join(lineas[:nodo.lineno - 1]) + reemplazo.rstrip() + "\n" + "".join(lineas[nodo.end_lineno:])


LOGIN = '''def iniciar_sesion(request):
    from .roles import destino_usuario

    if request.user.is_authenticated:
        return redirect(destino_usuario(request.user))

    error = None
    if request.method == "POST":
        dato = request.POST.get("dato", "").strip()
        password = request.POST.get("password", "")
        cuenta = Usuario.objects.filter(username=dato).first()
        if cuenta is None:
            coincidencias = list(Usuario.objects.filter(email__iexact=dato)[:2])
            cuenta = coincidencias[0] if len(coincidencias) == 1 else None
        usuario = authenticate(request, username=cuenta.get_username(), password=password) if cuenta else None
        if usuario is not None:
            barbero_inactivo = (
                not usuario.is_staff
                and Barbero.objects.filter(usuario=usuario, activo=False).exists()
            )
            if not barbero_inactivo:
                login(request, usuario)
                return redirect(destino_usuario(usuario))
        error = "Datos incorrectos o cuenta inactiva."

    return render(request, "principal/login.html", {"error": error})
'''


def preparar_cambios(nuevos):
    def leer(relativo):
        return (BASE / relativo).read_text(encoding="utf-8-sig")

    modelos = leer("principal/models.py")
    if "related_name=\"barbero\"" not in modelos:
        marca = "class Barbero(models.Model):\n"
        if modelos.count(marca) != 1:
            raise ValueError("La clase Barbero no coincide con la versión esperada.")
        campo = '''    usuario = models.OneToOneField(
        settings.AUTH_USER_MODEL,
        on_delete=models.PROTECT,
        related_name="barbero",
        null=True,
        blank=True,
    )
'''
        modelos = modelos.replace(marca, marca + campo, 1)
    if "def rol(self):" not in modelos:
        marca = "    def __str__(self):\n        return self.nombre_completo"
        if modelos.count(marca) != 1:
            raise ValueError("La clase Perfil no coincide con la versión esperada.")
        propiedad = '''    @property
    def rol(self):
        from .roles import rol_usuario
        return rol_usuario(self.usuario).capitalize()

'''
        modelos = modelos.replace(marca, propiedad + marca, 1)
    nuevos["principal/models.py"] = modelos

    vistas = leer("principal/views.py")
    vistas = reemplazar_funcion(vistas, "iniciar_sesion", LOGIN)
    nodos = [n for n in ast.parse(vistas).body if isinstance(n, ast.FunctionDef) and n.name == "registro"]
    if len(nodos) != 1:
        raise ValueError("No encuentro la función registro.")
    nodo = nodos[0]
    lineas = vistas.splitlines(keepends=True)
    registro = "".join(lineas[nodo.lineno - 1:nodo.end_lineno])
    registro = registro.replace('return redirect("inicio")', 'return redirect("panel_cliente")')
    if "destino_usuario" not in registro:
        registro = registro.replace("def registro(request):\n", '''def registro(request):
    from .roles import destino_usuario
    if request.user.is_authenticated:
        return redirect(destino_usuario(request.user))
''', 1)
    nuevos["principal/views.py"] = reemplazar_funcion(vistas, "registro", registro)

    formularios = leer("principal/forms.py")
    if "from django.db.models import Q" not in formularios:
        formularios = "from django.db.models import Q\n" + formularios
    if "Q(usuario__isnull=True)" not in formularios:
        marca = "Barbero.objects.filter(activo=True)"
        if marca not in formularios:
            raise ValueError("No encuentro el filtro de barberos de CitaForm.")
        formularios = formularios.replace(marca, marca + ".filter(Q(usuario__isnull=True) | Q(usuario__is_active=True))")
    nuevos["principal/forms.py"] = formularios

    rutas = leer("principal/urls.py")
    if 'name="panel_barbero"' not in rutas:
        rutas += '''

from . import roles_views

urlpatterns += [
    path("mi-acceso", roles_views.mi_acceso, name="mi_acceso"),
    path("mi-cuenta", roles_views.panel_cliente, name="panel_cliente"),
    path("barbero", roles_views.panel_barbero, name="panel_barbero"),
    path("barbero/citas/<int:cita_id>/estado", roles_views.estado_barbero, name="estado_barbero"),
    path("panel/cuentas", roles_views.gestionar_cuentas, name="gestionar_cuentas"),
    path("panel/cuentas/<int:usuario_id>/estado", roles_views.activar_cuenta, name="activar_cuenta"),
]
'''
    nuevos["principal/urls.py"] = rutas

    administracion = leer("principal/admin.py")
    if "from .cuentas_forms import BarberoVinculoForm" not in administracion:
        administracion = "from .cuentas_forms import BarberoVinculoForm\n" + administracion
    nodos = [n for n in ast.parse(administracion).body if isinstance(n, ast.ClassDef) and n.name == "BarberoAdmin"]
    if len(nodos) != 1:
        raise ValueError("No encuentro BarberoAdmin.")
    nodo = nodos[0]
    lineas = administracion.splitlines(keepends=True)
    clase = '''class BarberoAdmin(admin.ModelAdmin):
    form = BarberoVinculoForm
    list_display = ("nombre", "especialidad", "usuario", "activo")
    list_filter = ("activo",)
    search_fields = ("nombre", "especialidad", "usuario__username", "usuario__email")
    list_select_related = ("usuario",)
'''
    nuevos["principal/admin.py"] = "".join(lineas[:nodo.lineno - 1]) + clase + "".join(lineas[nodo.end_lineno:])

    ruta_menu = "principal/templates/principal/includes/encabezado.html"
    menu = leer(ruta_menu)
    if "panel_barbero" not in menu:
        patron = r"(\{% if user\.is_staff %\}.*?)(\{% endif %\})"
        extra = '''{% elif user.barbero %}
                <a class="capital-btn" href="{% url 'panel_barbero' %}">Mi agenda</a>
            {% else %}
                <a class="capital-btn" href="{% url 'panel_cliente' %}">Mi cuenta</a>
            {% endif %}'''
        menu, cantidad = re.subn(patron, lambda m: m.group(1) + extra, menu, count=1, flags=re.S)
        if cantidad != 1:
            raise ValueError("El encabezado compartido cambió. No se han escrito cambios.")
    nuevos[ruta_menu] = menu

    ruta_perfil = "principal/templates/principal/perfil.html"
    perfil = leer(ruta_perfil)
    patron = r"\{% if user\.is_staff %\}\s*Administrador\s*\{% else %\}\s*Cliente\s*\{% endif %\}"
    perfil, cantidad = re.subn(patron, "{{ datos_perfil.rol }}", perfil)
    if cantidad == 0 and "datos_perfil.rol" not in perfil:
        raise ValueError("No encuentro la etiqueta de rol en perfil.html.")
    nuevos[ruta_perfil] = perfil

    ruta_login = "principal/templates/principal/login.html"
    plantilla_login = leer(ruta_login)
    plantilla_login = plantilla_login.replace('type="email"', 'type="text"')
    plantilla_login = plantilla_login.replace("Correo electrónico</label>", "Correo o usuario</label>")
    nuevos[ruta_login] = plantilla_login

    ruta_panel = "principal/templates/principal/panel.html"
    panel = leer(ruta_panel)
    if "gestionar_cuentas" not in panel:
        marca = '<nav class="panel-enlaces"'
        posicion = panel.find(marca)
        if posicion != -1:
            fin = panel.find(">", posicion) + 1
            enlace = '\n<a href="{% url \'gestionar_cuentas\' %}" class="panel-boton">Usuarios y accesos</a>\n'
        else:
            posicion = panel.find('<nav class="accesos"')
            if posicion == -1:
                raise ValueError("No encuentro los accesos del panel.")
            fin = panel.find(">", posicion) + 1
            enlace = '\n<a href="{% url \'gestionar_cuentas\' %}" class="btn">Usuarios y accesos</a>\n'
        panel = panel[:fin] + enlace + panel[fin:]
    nuevos[ruta_panel] = panel
    return nuevos


def comando(*argumentos):
    print("\n> python manage.py " + " ".join(argumentos), flush=True)
    subprocess.run([sys.executable, str(BASE / "manage.py"), *argumentos], cwd=BASE, check=True)


def main():
    if not (BASE / "manage.py").is_file():
        raise ValueError("Copia este archivo junto a manage.py antes de ejecutarlo.")
    nuevos = json.loads(base64.b64decode(PAQUETE).decode("utf-8"))
    nuevos = preparar_cambios(nuevos)
    for relativo, contenido in nuevos.items():
        if relativo.endswith(".py"):
            ast.parse(contenido, filename=relativo)

    fecha = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    respaldo = BASE.parent / f"{BASE.name}_respaldo_roles_{fecha}"
    respaldo.mkdir()
    for relativo in nuevos:
        origen = BASE / relativo
        if origen.exists():
            destino = respaldo / relativo
            destino.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(origen, destino)

    sys.path.insert(0, str(BASE))
    import os
    os.environ.setdefault("DJANGO_SETTINGS_MODULE", "barberia_capital.settings")
    from importlib import import_module
    configuracion = import_module("barberia_capital.settings")
    bd = configuracion.DATABASES["default"]
    if bd["ENGINE"] != "django.db.backends.sqlite3":
        raise ValueError("Este instalador corresponde a la base SQLite de tu proyecto.")
    origen = Path(bd["NAME"])
    if origen.is_file():
        with sqlite3.connect(str(origen)) as conexion:
            with sqlite3.connect(str(respaldo / "db.sqlite3")) as copia:
                conexion.backup(copia)
    print(f"Respaldo de archivos y BD: {respaldo}", flush=True)

    for relativo, contenido in nuevos.items():
        destino = BASE / relativo
        destino.parent.mkdir(parents=True, exist_ok=True)
        destino.write_text(contenido, encoding="utf-8")
    comando("migrate", "--noinput")
    comando("check")
    comando("makemigrations", "--check", "--dry-run")
    comando("test", "principal.test_roles", "--noinput", "--verbosity", "1")
    comando("preparar_accesos")
    print("\nLISTO. Arranca el servidor e inicia sesión en /login con cada cuenta.")
    print("Administrador: /panel | Cliente: /mi-cuenta | Barbero: /barbero")


if __name__ == "__main__":
    try:
        main()
    except (OSError, ValueError, SyntaxError, subprocess.CalledProcessError) as error:
        print(f"\nNo se completó la instalación: {error}")
        print("Conserva la salida de la terminal para revisar el paso que falló.")
        sys.exit(1)
